# -*- coding: utf-8 -*-
"""Descriptions of the functions of single scenes (Tools/glsl_docs.py), keyed "File.frag::name".

S() builds an entry: the one-line description where the shader has none, the return value, the parameters.
"""


def S( brief=None, ret=None, **params ):
    """A scene-specific entry: the one-line description (where the shader has none), the return value, the parameters."""
    e = { "params": params }
    if brief:
        e[ "brief" ] = brief
    if ret:
        e[ "return" ] = ret
    return e


